import networkx as nx
import itertools

def indep_num(G):
    # exact max indep set
    nodes = list(G.nodes())
    for k in range(len(nodes), 0, -1):
        for s in itertools.combinations(nodes, k):
            sub = G.subgraph(s)
            if sub.number_of_edges() == 0:
                return k
    return 0

def edge_cover_num(G):
    # min edge cover
    edges = list(G.edges())
    nodes = set(G.nodes())
    for k in range(1, len(nodes) + 1):
        for es in itertools.combinations(edges, k):
            covered = set()
            for u, v in es:
                covered.add(u)
                covered.add(v)
            if covered == nodes:
                return k
    return len(nodes)

for idx, G in enumerate(nx.graph_atlas_g()):
    n = G.number_of_nodes()
    if n >= 2:
        deg = dict(G.degree())
        if min(deg.values()) > 0:
            a = indep_num(G)
            r = edge_cover_num(G)
            if a > r:
                print(f"FOUND COUNTEREXAMPLE! graph {idx}, n={n}, a={a}, r={r}, edges={list(G.edges())}")
                break
else:
    print("No counterexample in Graph Atlas (all graphs up to 7 vertices)!")
